// PLUTIOLABS SCRAPER v4 — PARENT CONFIG (single source of truth).
// Passed to the child on every batch; the child never defines its own.
try {
  return [{
    json: {
      // Claude no longer needs a key here. '🧠 Claude Enrich' in the CHILD is an
      // HTTP Request node using the n8n 'anthropicApi' credential (the same one
      // D3 uses), so the secret never enters config or execution data.
      claudeModel: 'claude-haiku-4-5',

      // NO API KEYS LIVE HERE ANYMORE (F-R13 closed, 2026-08-19).
      // Every outbound call is an HTTP Request node using an n8n credential:
      //   Anthropic  -> 'Anthropic account'  (anthropicApi)
      //   Apify      -> 'Apify API'          (httpHeaderAuth, api.apify.com only)
      //   ZeroBounce -> 'ZeroBounce API'     (httpQueryAuth,  api_key param)
      //   Instantly  -> 'Instantly API'      (httpHeaderAuth, api.instantly.ai only)
      // Config used to carry these in plaintext, and n8n writes config into the
      // execution data of EVERY batch - so the keys were readable by anyone with
      // access to the run history.
      //
      // These two are plain booleans, not secrets. They gate the two services
      // whose credentials are still placeholders - flip to true only once the
      // matching credential holds a real key.
      verifyEnabled: false,
      enrichEnabled: false,

      sheetsId:          'YOUR_SCRAPER_SHEET_ID',
      sheetsTabName:     'Outreach CRM',
      sheetsSnapshotTab: 'MCS Snapshot',

      mcsIndexUrl:      'https://findcertifiedinstallers.co.uk/api/index.json',
      mcsInstallersUrl: 'https://findcertifiedinstallers.co.uk/api/installers.json',

      mcsTechScope: ['solar_pv','ashp','battery','wshp','solar_thermal','eahp'],
      emailOnlyLtd: true,

      // ---- BATCHING ----
      // batchSize is reported only. The authoritative value is the literal on
      // the '🔁 Split In Batches' node (n8n requires a number there, not an
      // expression). KEEP THE TWO IN SYNC.
      batchSize: 500,
      // maxLeads caps the TOTAL run. 0 = full dataset (~5,603).
      // Kept small while proving the architecture.
      maxLeads: 500,
      leadOffset: 0,
      onlyCerts: [],

      apifyMaxResultsPerSearch: 40,
      apifyMaxPollMinutes: 20,
      // CAP SEMANTICS (F-R11): these are TOTALS for the whole run. Pack Batch
      // divides each by the batch count before handing it to a child, because
      // the child applies them PER EXECUTION. Left undivided, a '200' verify cap
      // became 2,400 across 12 batches - against a 100/month ZeroBounce tier.
      apifyLookupLimitTotal: 500,
      includeReviews: true,
      maxReviews: 20,
      // GATE 1 cap for the Tier-2 REVIEW scrape (run-wide total; Pack Batch
      // divides it per batch). Cost per lead: $0.004 place + 20 x $0.0005
      // reviews = $0.014. 100 leads = $1.40.
      apifyReviewLimitTotal: 100,
      // 'lowestRanking' deliberately. Complaints live in low-star reviews and
      // they are what create Templates A and B. For a 4.9-star business the
      // bottom 20 are still mostly positive, so bestReviewQuote (A-v2) survives;
      // for a 3.3-star business the complaints are the story anyway.
      reviewsSort: 'lowestRanking',
      ukCities: ['London','Manchester','Birmingham','Leeds'],
      ukKeywords: [
        'solar panel installer {city}',
        'solar PV installer {city}',
        'solar energy company {city}',
        'solar panel company {city}',
        'solar battery storage installer {city}',
        'solar installation {city}',
        'heat pump installer {city}',
        'air source heat pump installer {city}',
        'ground source heat pump installer {city}',
        'heat pump engineer {city}'
      ],

      competitorRadiusMiles:    10,
      competitorRadiusFallback: 15,
      competitorGapMin:         10,
      competitorGapMax:         150,

      minReviewsForP1: 8,

      // LEVER 3: a P2 lead whose competitor is this far ahead still gets A-lite.
      // The A-lite angle ("they are N reviews ahead") does not require the LEAD
      // to have many reviews - it lands harder when they have few. Set to 30 and
      // not 10 so we take dominant gaps without pulling in micro-businesses that
      // cannot afford a 2-10k engagement. Raise it to tighten, lower to widen.
      aLiteP2GapMin: 30,

      reviewsLowCount: 5,
      reviewsHighCount: 3,
      // GATE 2 value. maxLeads 500 + batchSize 500 = one batch, so this is also
      // the per-batch figure. Raise to 0 (unlimited) only after Gate 2 passes.
      maxClaudeCallsTotal: 100,
      maxInstantlyCallsTotal: 0,
      maxVerifyCallsTotal: 200
    }
  }];
} catch (e) {
  return [{ json: { _error: 'Config failed: ' + e.message } }];
}

try {
  var payload = $input.first().json;
  var rows = (payload && payload.installers) ? payload.installers : [];
  var idx = {};
  try { idx = $('📡 Fetch MCS Index').first().json || {}; } catch (e) { idx = {}; }
  var generatedAt = idx.generated_at || '';
  if (!rows.length) { return [{ json: { _error: 'MCS fetch returned no installers' } }]; }
  var out = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    r.source = 'mcs';
    r.mcsGeneratedAt = generatedAt;
    out.push({ json: r });
  }
  return out;
} catch (e) {
  return [{ json: { _error: 'Split MCS failed: ' + e.message } }];
}

// Stage 1b — scope filter + the 5 mandatory fixes from the 2026-08-15 data audit.
try {
  var cfg = $('⚙️ Config').first().json;
  var scope = cfg.mcsTechScope || [];
  var ltdOnly = cfg.emailOnlyLtd !== false;
  var maxLeads = cfg.maxLeads || 0;
  var onlyCerts = cfg.onlyCerts || [];
  var leadOffset = cfg.leadOffset || 0;
  var matchedIdx = 0;
  var items = $input.all();

  var FREE = ['gmail.com','hotmail.com','hotmail.co.uk','yahoo.com','yahoo.co.uk',
              'outlook.com','icloud.com','btinternet.com','live.co.uk','aol.com',
              'sky.com','msn.com','me.com'];

  // Scotland / Wales / NI postcode areas. `region` is England-only — never filter on it.
  var SCOT = ['AB','DD','DG','EH','FK','G','HS','IV','KA','KW','KY','ML','PA','PH','TD','ZE'];
  var WALES = ['CF','LD','LL','NP','SA'];

  function pcArea(pc) {
    var m = String(pc || '').toUpperCase().match(/^[A-Z]{1,2}/);
    return m ? m[0] : '';
  }
  function country(pc) {
    var a = pcArea(pc);
    if (a === 'BT') return 'Northern Ireland';
    if (SCOT.indexOf(a) !== -1) return 'Scotland';
    if (WALES.indexOf(a) !== -1) return 'Wales';
    return 'England';
  }
  function isLtd(name) {
    var n = String(name || '').toLowerCase().replace(/\.+$/, '').trim();
    return /\b(ltd|limited|llp|plc)$/.test(n);
  }
  function fixSite(w) {
    var s = String(w || '').trim();
    if (!s) return '';
    if (/\s/.test(s)) return '';
    if (!/\.[a-z]{2,}/i.test(s)) return '';
    if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
    return s.replace(/\/+$/, '');
  }
  function normPhone(p) {
    var d = String(p || '').replace(/\D/g, '');
    if (d.indexOf('44') === 0) d = d.substring(2);
    if (d.indexOf('0') === 0) d = d.substring(1);
    // F-R7: preserve non-standard lengths - blanking them destroyed working
    // numbers and created blank match keys (F-R6).
    return d.length >= 7 ? d : '';
  }
  function e164(k) { return k ? '+44' + k : ''; }

  var out = [];
  var stats = { seen: 0, outOfScope: 0, notLtd: 0, badGeo: 0, kept: 0,
                pecrRisk: 0, badSite: 0, badPhone: 0, skippedByOffset: 0 };

  for (var i = 0; i < items.length; i++) {
    // F-R16 FIX: slicing MOVED to '🧭 Build Competitor Index'. Capping here shrank
    // the competitor index in proportion to maxLeads, which silently collapsed
    // every A-route to D. See the note in that node.
    var r = items[i].json;
    if (!r || r._error) { continue; }
    stats.seen++;

    if (onlyCerts.length && onlyCerts.indexOf(r.certification_number) === -1) { continue; }

    var techs = r.technologies || [];
    var inScope = false;
    for (var t = 0; t < techs.length; t++) {
      if (scope.indexOf(techs[t]) !== -1) { inScope = true; break; }
    }
    if (!inScope) { stats.outOfScope++; continue; }

    var lat = Number(r.latitude), lon = Number(r.longitude);
    if (!(lat >= 49.8 && lat <= 60.9 && lon >= -8.7 && lon <= 1.9)) {
      stats.badGeo++; continue;
    }

    matchedIdx++;
    // F-R16 FIX: leadOffset also moved to '🧭 Build Competitor Index'.

    var ltd = isLtd(r.name);
    if (ltdOnly && !ltd) { stats.notLtd++; }

    var site = fixSite(r.website);
    if (r.website && !site) { stats.badSite++; }

    var phone = normPhone(r.telephone);
    if (r.telephone && !phone) { stats.badPhone++; }

    var email = String(r.email || '').trim().toLowerCase();
    var emailDomain = email.indexOf('@') > -1 ? email.split('@')[1] : '';
    var freeMailbox = FREE.indexOf(emailDomain) !== -1;
    var emailValid = /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email);

    var pecrRisk = (!ltd && freeMailbox);
    if (pecrRisk) { stats.pecrRisk++; }

    var emailable = emailValid && !pecrRisk && (!ltdOnly || ltd);

    stats.kept++;
    out.push({ json: {
      source: 'mcs',
      mcsGeneratedAt: r.mcsGeneratedAt || '',
      companyName: r.name,
      certNumber: r.certification_number,
      certBody: r.certification_body,
      technologies: techs.join(', '),
      busRegistered: !!r.bus_registered,
      address: r.address,
      postcode: r.postcode,
      town: r.town,
      county: r.county,
      country: country(r.postcode),
      latitude: lat,
      longitude: lon,
      phone: e164(phone),
      phoneKey: phone,
      phoneRaw: r.telephone || '',
      email: email,
      emailValid: emailValid,
      emailFreeMailbox: freeMailbox,
      website: site,
      googleRating: (r.google_rating === null || r.google_rating === undefined) ? null : Number(r.google_rating),
      reviewCount: (r.google_review_count === null || r.google_review_count === undefined) ? null : Number(r.google_review_count),
      googleMatched: (r.google_review_count !== null && r.google_review_count !== undefined),
      entityType: ltd ? 'ltd' : 'unknown',
      pecrRisk: pecrRisk,
      emailable: emailable,
      mcsPageUrl: r.page_url || ''
    }});
  }

  if (!out.length) {
    return [{ json: { _error: 'MCS filter produced 0 leads', _stats: stats } }];
  }
  out[0].json._stats = stats;
  return out;
} catch (e) {
  return [{ json: { _error: 'MCS filter failed: ' + e.message } }];
}

// Builds ONE global competitor index from the whole filtered set, then hands it
// to every batch. This is what stops batching from wrecking competitor matching
// (F-R2: full pool ~100% of eligible leads, a 500-lead slice only 48.6%).
//
// Deliberately compact - name, coords, reviews, rating, categories - because it
// rides along with every child call. The full records never leave the parent.
//
// NOTE: leads whose review counts arrive later via the Apify lookup are NOT in
// this index (MCS only carries review data for ~47%). Run the enrichment pass
// first, then re-run competitor matching, once the Apify key exists.
try {
  var items = $input.all();
  var index = [];
  var out = [];
  var withCoords = 0;

  // F-R12 FIX: two-pass competitor matching.
  // MCS only carries review counts for ~47% of leads, so an index built purely
  // from the in-memory set can never match the other ~2,978 - they would stay on
  // Template D forever no matter how good the Apify run was.
  // So: merge in review counts already written to the CRM by a previous
  // enrichment pass. Run the parent again after an Apify pass and the index
  // automatically improves. Empty sheet (first ever run) falls back to memory.
  var sheetIdx = {};
  var sheetHits = 0;
  try {
    var vr = $('📖 Read CRM Index').first().json.valueRanges || [];
    var jk = (vr[0] && vr[0].values) || [];   // J = Review Count, K = Business Category
    var bf = (vr[1] && vr[1].values) || [];   // BF = Row Key
    for (var s = 1; s < jk.length; s++) {     // row 0 is the header
      var kRow = bf[s] || [];
      var key = kRow[0] ? String(kRow[0]) : '';
      if (!key) { continue; }
      var jRow = jk[s] || [];
      var rc = (jRow[0] !== undefined && jRow[0] !== '') ? Number(jRow[0]) : null;
      if (rc === null || isNaN(rc)) { continue; }
      sheetIdx[key] = { reviewCount: rc, categories: jRow[1] ? String(jRow[1]) : '' };
      sheetHits++;
    }
  } catch (e) { /* first run - no sheet data yet */ }

  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error) { continue; }
    out.push({ json: r });

    if (typeof r.latitude === 'number' && typeof r.longitude === 'number') {
      withCoords++;
      var rKey = r.certNumber ? ('MCS:' + r.certNumber)
                              : ('NM:' + String(r.companyName || '').toLowerCase());
      // Prefer the CRM's review count - it reflects any prior Apify enrichment.
      var sEntry = sheetIdx[rKey];
      var effRc = (sEntry && sEntry.reviewCount > 0) ? sEntry.reviewCount
                                                     : (r.reviewCount || 0);
      if (effRc > 0) {
        index.push({
          key: rKey,
          companyName: r.companyName || '',
          latitude: r.latitude,
          longitude: r.longitude,
          reviewCount: effRc,
          googleRating: r.googleRating || 0,
          openingHours: r.openingHours || '',
          categories: r.categories || (sEntry ? sEntry.categories : '')
        });
      }
    }
  }

  if (!out.length) { return [{ json: { _error: 'Build Index got 0 leads' } }]; }

  // ---- F-R16 FIX ----
  // The index above is built from the FULL reconciled pool. ONLY NOW do we slice
  // to the leads this run will actually enrich.
  //
  // Slicing used to happen upstream in '🔎 MCS Filter & Normalize', which shrank
  // the competitor index in proportion to maxLeads: a 25-lead run produced a
  // 21-entry index, so almost nothing fell inside the 10-mile radius, no gap was
  // found, and every A-route collapsed to D. Competitor gap is what creates
  // A / A-v2 / A-lite - the highest-reply-rate templates - so the old ordering
  // silently destroyed the best leads in any sliced run.
  var cfgS = {};
  try { cfgS = $('⚙️ Config').first().json || {}; } catch (eC) { }
  var maxLeads = cfgS.maxLeads || 0;
  var leadOffset = cfgS.leadOffset || 0;

  var emitted = out;
  if (leadOffset > 0) { emitted = emitted.slice(leadOffset); }
  if (maxLeads > 0) { emitted = emitted.slice(0, maxLeads); }
  if (!emitted.length) {
    return [{ json: { _error: 'Slice produced 0 leads - leadOffset ' + leadOffset + ' is past the end of ' + out.length + ' records' } }];
  }

  // Attach to the first item only - same pattern as _stats. Pack Batch reads it
  // via $('🧭 Build Competitor Index').first().json._index
  emitted[0].json._index = index;
  emitted[0].json._indexStats = {
    totalLeads: out.length,
    indexedFrom: out.length,
    emitted: emitted.length,
    withCoords: withCoords,
    indexSize: index.length,
    sheetReviewCountsMerged: sheetHits,
    leadOffset: leadOffset,
    maxLeads: maxLeads
  };
  return emitted;
} catch (e) {
  return [{ json: { _error: 'Build Competitor Index failed: ' + e.message } }];
}

// Collapses one batch into a SINGLE payload item for the child:
//   { config, index, leads[], batchIndex }
try {
  var cfg = $('⚙️ Config').first().json;
  var idx = [];
  try { idx = $('🧭 Build Competitor Index').first().json._index || []; } catch (e) { idx = []; }

  var items = $input.all();
  var leads = [];
  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error) { continue; }
    // Strip the parent-only bookkeeping fields before shipping.
    if (r._index) { delete r._index; }
    if (r._indexStats) { delete r._indexStats; }
    if (r._stats) { delete r._stats; }
    leads.push(r);
  }

  if (!leads.length) { return [{ json: { _error: 'Pack Batch got 0 leads' } }]; }

  // F-R11 FIX: the child applies spend caps PER EXECUTION, so a run-wide total
  // has to be divided by the batch count before it is handed over. Without this
  // a '200' verify cap became 200 x 12 = 2,400 ZeroBounce credits.
  var totalLeads = 0;
  try { totalLeads = $('🧭 Build Competitor Index').first().json._indexStats.totalLeads || 0; } catch (e) {}
  var size = cfg.batchSize || leads.length;
  var batches = Math.max(1, Math.ceil(totalLeads / size));
  function perBatch(total) {
    if (!total || total <= 0) { return 0; }          // 0 = unlimited, preserve it
    return Math.max(1, Math.ceil(total / batches));
  }

  var childCfg = JSON.parse(JSON.stringify(cfg));
  childCfg.apifyLookupLimit  = perBatch(cfg.apifyLookupLimitTotal);
  childCfg.apifyReviewLimit  = perBatch(cfg.apifyReviewLimitTotal);
  childCfg.maxClaudeCalls    = perBatch(cfg.maxClaudeCallsTotal);
  childCfg.maxInstantlyCalls = perBatch(cfg.maxInstantlyCallsTotal);
  childCfg.maxVerifyCalls    = perBatch(cfg.maxVerifyCallsTotal);
  childCfg._batchCount = batches;

  return [{ json: {
    config: childCfg,
    index: idx,
    leads: leads,
    batchIndex: $runIndex,
    batchLeadCount: leads.length,
    indexSize: idx.length,
    batchCount: batches,
    perBatchCaps: {
      apifyLookupLimit: childCfg.apifyLookupLimit,
      apifyReviewLimit: childCfg.apifyReviewLimit,
      maxClaudeCalls: childCfg.maxClaudeCalls,
      maxVerifyCalls: childCfg.maxVerifyCalls
    }
  }}];
} catch (e) {
  return [{ json: { _error: 'Pack Batch failed: ' + e.message } }];
}

// Fires once, on the Split In Batches 'done' output.
try {
  var cfg = $('⚙️ Config').first().json;
  var idxStats = {};
  var filterStats = {};
  try { idxStats = $('🧭 Build Competitor Index').first().json._indexStats || {}; } catch (e) {}
  try { filterStats = $('🔎 MCS Filter & Normalize').first().json._stats || {}; } catch (e) {}

  var totalLeads = idxStats.totalLeads || 0;
  var size = cfg.batchSize || 0;
  var batches = size ? Math.ceil(totalLeads / size) : 0;

  return [{ json: {
    _summary: 'v4 batched run complete',
    totalLeads: totalLeads,
    batchSize: size,
    batchesRun: batches,
    competitorIndexSize: idxStats.indexSize || 0,
    leadsWithCoords: idxStats.withCoords || 0,
    filterStats: filterStats,
    maxLeadsCap: cfg.maxLeads,
    note: 'Per-batch counts are in the CHILD executions. Verify the CRM with the Integrity Check utility.'
  }}];
} catch (e) {
  return [{ json: { _error: 'Run Summary failed: ' + e.message } }];
}

// Stage 1d — reconcile MCS + Maps into ONE canonical record shape, then dedupe.
// CRITICAL: this is the canonicalisation step. It maps town->city,
// country->ukCountry, technologies->categories (which drives Trade / Trade
// Scene, F-A1) and derives the WhatsApp signal. Skipping it writes rows with a
// blank City / Business Category / UK Country and a generic trade fallback.
try {
  var items = $input.all();

  var TECH_LABEL = {
    solar_pv: 'Solar panel installer', solar_thermal: 'Solar thermal installer',
    battery: 'Solar battery storage', ashp: 'Heat pump installer',
    wshp: 'Heat pump installer', eahp: 'Heat pump installer',
    gshp: 'Heat pump installer', sahp: 'Heat pump installer',
    gahp: 'Heat pump installer', biomass: 'Biomass installer',
    wind_turbine: 'Wind turbine installer', micro_chp: 'Micro CHP installer'
  };
  var TECH_ORDER = ['solar_pv','solar_thermal','battery','ashp','wshp','eahp',
                    'gshp','sahp','gahp','biomass','wind_turbine','micro_chp'];

  function techToCategories(techStr) {
    var raw = String(techStr || '').split(',');
    var have = {};
    for (var i = 0; i < raw.length; i++) {
      var t = raw[i].replace(/\s/g, '');
      if (t) { have[t] = true; }
    }
    var out = [];
    for (var o = 0; o < TECH_ORDER.length; o++) {
      var key = TECH_ORDER[o];
      if (have[key]) {
        var lab = TECH_LABEL[key];
        if (lab && out.indexOf(lab) === -1) { out.push(lab); }
      }
    }
    return out.join(', ');
  }

  function normPhone(phone) {
    var raw = String(phone || '');
    var p = '';
    for (var ci = 0; ci < raw.length; ci++) {
      var ch = raw.charAt(ci);
      if (ch >= '0' && ch <= '9') { p += ch; }
      else if (ch === '+' && p.length === 0) { p += ch; }
    }
    if (p.length < 5) { return ''; }
    if (p.charAt(0) === '+') { return p; }
    if (p.charAt(0) === '0') { return '+44' + p.substring(1); }
    if (p.length > 10 && p.substring(0, 2) === '44') { return '+' + p; }
    return p;
  }
  function phoneKeyOf(e164) {
    var d = String(e164 || '').replace(/\D/g, '');
    if (d.indexOf('44') === 0) { d = d.substring(2); }
    if (d.indexOf('0') === 0) { d = d.substring(1); }
    return d.length >= 7 ? d : '';   // F-R7: preserve non-standard lengths
  }
  function domainOf(w) {
    var d = String(w || '').toLowerCase().trim();
    if (!d) { return ''; }
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }
  function isMob(e164) { return String(e164 || '').indexOf('+447') === 0; }

  function canonMcs(r) {
    var ph = r.phone || '';
    return {
      companyName: r.companyName || '', city: r.town || '', country: 'UK',
      ukCountry: r.country || '', postcode: r.postcode || '', county: r.county || '',
      address: r.address || '',
      phone: ph, phoneKey: r.phoneKey || phoneKeyOf(ph),
      website: r.website || '', email: r.email || '',
      firstName: '', ownerName: '', linkedinUrl: '',
      source: 'mcs',
      googleRating: r.googleRating || 0,
      reviewCount: (r.reviewCount === null || r.reviewCount === undefined) ? 0 : r.reviewCount,
      googleMatched: !!r.googleMatched,
      googleMapsUrl: '', categories: techToCategories(r.technologies),
      openingHours: '', hoursKnown: false,
      businessAttributes: '', socialLinks: '', reviews: [],
      latitude: r.latitude, longitude: r.longitude,
      certNumber: r.certNumber || '', certBody: r.certBody || '',
      technologies: r.technologies || '', busRegistered: !!r.busRegistered,
      entityType: r.entityType || 'unknown', pecrRisk: !!r.pecrRisk,
      emailable: !!r.emailable, emailSource: r.email ? 'mcs' : '',
      mcsGeneratedAt: r.mcsGeneratedAt || '', mcsPageUrl: r.mcsPageUrl || '',
      isMobile: isMob(ph), waLink: ''
    };
  }

  function canonMaps(r) {
    var ph = normPhone(r.phone);
    return {
      companyName: r.companyName || '', city: r.city || '', country: 'UK',
      ukCountry: '', postcode: r.postcode || '', county: '', address: r.address || '',
      phone: ph, phoneKey: phoneKeyOf(ph),
      website: r.website || '', email: '',
      firstName: '', ownerName: '', linkedinUrl: '',
      source: 'maps',
      googleRating: r.googleRating || 0, reviewCount: r.reviewCount || 0,
      googleMatched: true,
      googleMapsUrl: r.googleMapsUrl || '', categories: r.categories || '',
      openingHours: r.openingHours || '', hoursKnown: !!r.openingHours,
      businessAttributes: r.businessAttributes || '', socialLinks: r.socialLinks || '',
      reviews: r.reviews || [],
      latitude: r.latitude, longitude: r.longitude,
      certNumber: '', certBody: '', technologies: '', busRegistered: false,
      entityType: 'unknown', pecrRisk: false, emailable: false, emailSource: '',
      mcsGeneratedAt: '', mcsPageUrl: '',
      isMobile: isMob(ph), waLink: r.waLink || ''
    };
  }

  var byPhone = {}, byDomain = {};
  var out = [];
  var stats = { mcsIn: 0, mapsIn: 0, mapsSkipped: 0, merged: 0, mapsNetNew: 0, dropped: 0 };

  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error || r._skipped) {
      if (r && r._skipped) { stats.mapsSkipped++; }
      continue;
    }
    if (r.source !== 'mcs') { continue; }
    stats.mcsIn++;
    var c = canonMcs(r);
    if (!c.companyName) { stats.dropped++; continue; }
    out.push(c);
    if (c.phoneKey) { byPhone[c.phoneKey] = c; }
    var d = domainOf(c.website);
    if (d) { byDomain[d] = c; }
  }

  for (var j = 0; j < items.length; j++) {
    var m = items[j].json;
    if (!m || m._error || m._skipped) { continue; }
    if (m.source !== 'maps') { continue; }
    stats.mapsIn++;

    var cm = canonMaps(m);
    if (!cm.companyName) { stats.dropped++; continue; }

    var dm = domainOf(cm.website);
    var hit = null;
    if (cm.phoneKey && byPhone[cm.phoneKey]) { hit = byPhone[cm.phoneKey]; }
    else if (dm && byDomain[dm]) { hit = byDomain[dm]; }

    if (hit) {
      hit.source = 'both';
      hit.googleRating = cm.googleRating || hit.googleRating;
      hit.reviewCount = cm.reviewCount || hit.reviewCount;
      hit.googleMatched = true;
      hit.googleMapsUrl = cm.googleMapsUrl || hit.googleMapsUrl;
      hit.openingHours = cm.openingHours || hit.openingHours;
      hit.hoursKnown = hit.hoursKnown || cm.hoursKnown;
      hit.businessAttributes = cm.businessAttributes || hit.businessAttributes;
      hit.socialLinks = cm.socialLinks || hit.socialLinks;
      hit.reviews = (cm.reviews && cm.reviews.length) ? cm.reviews : hit.reviews;
      hit.waLink = hit.waLink || cm.waLink;
      if (!hit.categories) { hit.categories = cm.categories; }
      if (!hit.website) { hit.website = cm.website; }
      if (hit.latitude === null || hit.latitude === undefined) { hit.latitude = cm.latitude; }
      if (hit.longitude === null || hit.longitude === undefined) { hit.longitude = cm.longitude; }
      stats.merged++;
    } else {
      out.push(cm);
      if (cm.phoneKey) { byPhone[cm.phoneKey] = cm; }
      if (dm) { byDomain[dm] = cm; }
      stats.mapsNetNew++;
    }
  }

  for (var k = 0; k < out.length; k++) {
    var o = out[k];
    if (o.waLink) { o.waSignal = 'wa-link'; o.waNumber = o.phone; }
    else if (o.isMobile) { o.waSignal = 'mobile'; o.waNumber = o.phone; }
    else { o.waSignal = 'none'; o.waNumber = ''; }
  }

  out.sort(function(a, b) {
    var rank = { both: 0, mcs: 1, maps: 2 };
    return (rank[a.source] || 3) - (rank[b.source] || 3);
  });

  if (!out.length) {
    return [{ json: { _error: 'Reconcile produced 0 leads', _stats: stats } }];
  }

  var results = [];
  for (var z = 0; z < out.length; z++) { results.push({ json: out[z] }); }
  results[0].json._reconcileStats = stats;
  return results;
} catch (e) {
  return [{ json: { _error: 'Reconcile failed: ' + e.message } }];
}

// PLUTIOLABS SCRAPER v4 — PARENT CONFIG (single source of truth).
